from typing import List

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        # Try each candidate and count by a full scan.
        for x in nums:
            count = 0
            for y in nums:
                if x == y:
                    count += 1
            if count == 1:
                return x
        return 0

