from typing import List

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        freq = {}
        for x in nums:
            freq[x] = freq.get(x, 0) + 1
        for x, count in freq.items():
            if count == 1:
                return x
        return 0

